import{_ as e,o as a,c as r,a5 as o}from"./chunks/framework.B-qY3dMa.js";const x=JSON.parse('{"title":"NextChat 接入指南","description":"","frontmatter":{"title":"NextChat 接入指南","date":"2026-05-18T00:00:00.000Z","category":"拓展","tags":["NextChat","AI客户端","接入教程","开源"]},"headers":[],"relativePath":"connect/nextchat.md","filePath":"connect/nextchat.md","lastUpdated":1779073000000}'),h={name:"connect/nextchat.md"};function n(d,t,s,c,i,l){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="nextchat-接入指南" tabindex="-1">NextChat 接入指南 <a class="header-anchor" href="#nextchat-接入指南" aria-label="Permalink to &quot;NextChat 接入指南&quot;">​</a></h1><p>开源轻量的私人 ChatGPT 应用，支持网页版和桌面客户端。</p><p><strong>预计用时：3 分钟 · 支持平台：网页版 / 桌面客户端 · GitHub Stars：80k+</strong></p><hr><h2 id="什么是-nextchat" tabindex="-1">什么是 NextChat？ <a class="header-anchor" href="#什么是-nextchat" aria-label="Permalink to &quot;什么是 NextChat？&quot;">​</a></h2><p>NextChat（原名 ChatGPT-Next-Web）是 GitHub 上 Stars 最多的开源 ChatGPT 前端项目之一。提供桌面客户端（Windows / macOS / Linux）和网页版，界面简洁，支持预设面具、Markdown 渲染、对话导出等功能。</p><hr><h2 id="step-01-获取-nextchat" tabindex="-1">Step 01：获取 NextChat <a class="header-anchor" href="#step-01-获取-nextchat" aria-label="Permalink to &quot;Step 01：获取 NextChat&quot;">​</a></h2><h3 id="方式一-下载桌面客户端-推荐" tabindex="-1">方式一：下载桌面客户端（推荐） <a class="header-anchor" href="#方式一-下载桌面客户端-推荐" aria-label="Permalink to &quot;方式一：下载桌面客户端（推荐）&quot;">​</a></h3><p>前往 <a href="https://github.com/ChatGPTNextWeb/NextChat/releases" target="_blank" rel="noreferrer">GitHub Releases 页面</a>，根据系统下载对应安装包，双击安装即可。</p><h3 id="方式二-直接访问官方-demo" tabindex="-1">方式二：直接访问官方 Demo <a class="header-anchor" href="#方式二-直接访问官方-demo" aria-label="Permalink to &quot;方式二：直接访问官方 Demo&quot;">​</a></h3><p>可直接访问 <a href="https://app.nextchat.dev" target="_blank" rel="noreferrer">app.nextchat.dev</a> 使用网页版（需要配置 API Key）。</p><hr><h2 id="step-02-获取熊猫token-api-key" tabindex="-1">Step 02：获取熊猫Token API Key <a class="header-anchor" href="#step-02-获取熊猫token-api-key" aria-label="Permalink to &quot;Step 02：获取熊猫Token API Key&quot;">​</a></h2><h3 id="_1-登录并创建令牌" tabindex="-1">1. 登录并创建令牌 <a class="header-anchor" href="#_1-登录并创建令牌" aria-label="Permalink to &quot;1. 登录并创建令牌&quot;">​</a></h3><p>访问 <a href="https://www.pandatoken.net" target="_blank" rel="noreferrer">www.pandatoken.net</a>，进入「控制台」→「令牌」，新建令牌并复制。</p><hr><h2 id="step-03-在-nextchat-中配置" tabindex="-1">Step 03：在 NextChat 中配置 <a class="header-anchor" href="#step-03-在-nextchat-中配置" aria-label="Permalink to &quot;Step 03：在 NextChat 中配置&quot;">​</a></h2><h3 id="_1-打开设置" tabindex="-1">1. 打开设置 <a class="header-anchor" href="#_1-打开设置" aria-label="Permalink to &quot;1. 打开设置&quot;">​</a></h3><p>启动 NextChat 后，点击左下角「设置」图标（齿轮）进入设置页面。</p><h3 id="_2-启用自定义接口" tabindex="-1">2. 启用自定义接口 <a class="header-anchor" href="#_2-启用自定义接口" aria-label="Permalink to &quot;2. 启用自定义接口&quot;">​</a></h3><p>向下滚动找到「自定义接口」开关，<strong>打开</strong>它。</p><h3 id="_3-填写接口信息" tabindex="-1">3. 填写接口信息 <a class="header-anchor" href="#_3-填写接口信息" aria-label="Permalink to &quot;3. 填写接口信息&quot;">​</a></h3><table tabindex="0"><thead><tr><th>配置项</th><th>填写内容</th></tr></thead><tbody><tr><td>接口地址 (OpenAI Endpoint)</td><td><code>https://www.pandatoken.net</code></td></tr><tr><td>API Key</td><td>你从平台复制的令牌</td></tr><tr><td>自定义模型名</td><td>例如 <code>deepseek-v3,gpt-4o</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">注意</p><p>NextChat 的接口地址填根域名 <code>https://www.pandatoken.net</code>，<strong>不要</strong>加 <code>/v1</code>，它会自动拼接路径。</p></div><h3 id="_4-选择模型并开始对话" tabindex="-1">4. 选择模型并开始对话 <a class="header-anchor" href="#_4-选择模型并开始对话" aria-label="Permalink to &quot;4. 选择模型并开始对话&quot;">​</a></h3><p>在「模型」下拉框中选择你填写的自定义模型，关闭设置，即可在聊天界面开始使用。</p><hr><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>模型选择器里没有想要的模型</strong></p><p>在设置的「自定义模型名」中，输入模型 ID（多个用英文逗号分隔），例如 <code>deepseek-v3,deepseek-r1,gpt-4o</code>，保存后下拉框就会出现这些模型。</p><p><strong>设置完后发送消息提示 404</strong></p><p>确认接口地址没有加 <code>/v1</code>，NextChat 会自动补全完整路径。</p><hr><p>配置完成！NextChat 已成功接入熊猫Token平台，简洁界面畅享所有模型。</p>',35)])])}const b=e(h,[["render",n]]);export{x as __pageData,b as default};
